const data = $input.first().json.body;

const companyName = data.company_name;
const website = data.website || '';
const notes = data.notes || '';
const appointments = data.appointments_per_week || 0;

const text = (website + ' ' + notes + ' ' + companyName).toLowerCase();

let sector = 'servicios profesionales';
let useCase = 'captacion';
let adjectives = 'profesional, cercano y eficiente';
let agentName = 'Ana';
let faqs = '';

if (text.match(/dental|dentist|odontol|ortodoncia|clinica dental/)) {
  sector = 'salud dental';
  useCase = 'citas';
  adjectives = 'profesional, tranquilizador y cercano';
  agentName = 'Laura';
  faqs = `1. ¿Cuánto cuesta una limpieza dental? → "Los precios dependen del tratamiento. Nuestro equipo te dará un presupuesto personalizado en tu primera visita."
2. ¿Hacéis ortodoncia invisible? → "Sí, ofrecemos varias opciones de ortodoncia. ¿Te gustaría que agendemos una consulta de valoración?"
3. ¿Aceptáis seguros dentales? → "Trabajamos con las principales aseguradoras. Dime cuál tienes y te confirmo."
4. ¿Cuánto dura un blanqueamiento? → "El tratamiento suele durar entre 45 minutos y una hora. Los resultados son visibles desde la primera sesión."`;
} else if (text.match(/inmobil|real estate|vivienda|piso|alquiler|propiedad/)) {
  sector = 'inmobiliaria';
  useCase = 'captacion';
  adjectives = 'profesional, persuasivo y resolutivo';
  agentName = 'Carlos';
  faqs = `1. ¿Tenéis pisos en zona centro? → "Tenemos varias opciones disponibles. ¿Me dices tu presupuesto orientativo y el número de habitaciones que necesitas?"
2. ¿Hacéis valoraciones gratuitas? → "Sí, valoramos tu propiedad sin compromiso. ¿Cuándo te iría bien que pasase un agente?"
3. ¿Cuánto tardáis en vender un piso? → "Depende de la zona y el precio, pero de media nuestros clientes venden en menos de 3 meses."
4. ¿Gestionáis el papeleo? → "Nos encargamos de todo: contrato, notaría, registro. Tú no te preocupas de nada."`;
} else if (text.match(/gym|gimnasio|fitness|deport|entren|crossfit/)) {
  sector = 'fitness y deporte';
  useCase = 'captacion';
  adjectives = 'dinámico, motivador y cercano';
  agentName = 'Alex';
  faqs = `1. ¿Cuánto cuesta la mensualidad? → "Tenemos varios planes según lo que busques. ¿Te gustaría que te contase las opciones?"
2. ¿Puedo hacer una clase de prueba? → "¡Claro! La primera clase es gratuita. ¿Qué día te vendría bien?"
3. ¿Tenéis horarios de mañana? → "Abrimos desde las 7 de la mañana. Hay clases dirigidas a todas las horas."
4. ¿Hay parking? → "Sí, tenemos parking gratuito para socios junto al centro."`;
} else if (text.match(/abogad|legal|jurídic|juridic|despacho|bufete|notari/)) {
  sector = 'servicios legales';
  useCase = 'captacion';
  adjectives = 'profesional, discreto y resolutivo';
  agentName = 'Asistente del despacho';
  faqs = `1. ¿La primera consulta es gratuita? → "Ofrecemos una primera valoración sin compromiso para entender su caso."
2. ¿En qué áreas trabajan? → "Cubrimos derecho civil, mercantil, laboral y fiscal. ¿En qué materia necesita asesoramiento?"
3. ¿Cuánto tarda un proceso? → "Los plazos varían según el tipo de procedimiento. Le daremos una estimación realista en la consulta."
4. ¿Trabajan con empresas? → "Sí, asesoramos tanto a particulares como a empresas de todos los tamaños."`;
} else if (text.match(/estetic|estetica|belleza|spa|peluquer|beauty|salon/)) {
  sector = 'estética y belleza';
  useCase = 'citas';
  adjectives = 'amable, profesional y cercano';
  agentName = 'Sofía';
  faqs = `1. ¿Qué tratamientos faciales ofrecéis? → "Tenemos limpieza facial, hidratación profunda, radiofrecuencia y más. ¿Buscas algo específico?"
2. ¿Cuánto dura una sesión? → "Depende del tratamiento, entre 30 y 90 minutos. Te lo confirmo al reservar."
3. ¿Hacéis bonos? → "Sí, tenemos packs con descuento. Nuestro equipo te explicará las opciones."
4. ¿Puedo cancelar mi cita? → "Puedes cancelar o cambiar tu cita con 24 horas de antelación sin ningún coste."`;
} else if (text.match(/restauran|comida|gastro|bar|cater|food|delivery/)) {
  sector = 'hostelería y restauración';
  useCase = 'citas';
  adjectives = 'amable, eficiente y servicial';
  agentName = 'María';
  faqs = `1. ¿Tenéis menú del día? → "Sí, cambiamos el menú cada día. ¿Quieres que te cuente el de hoy?"
2. ¿Se puede reservar mesa? → "Por supuesto. ¿Para cuántas personas y qué día?"
3. ¿Hacéis eventos privados? → "Sí, organizamos eventos y celebraciones. Nuestro equipo te prepara un presupuesto."
4. ¿Tenéis opciones veganas? → "Siempre tenemos opciones veganas y sin gluten en la carta."`;
} else if (text.match(/tech|software|saas|digital|app|desarrollo|programac/)) {
  sector = 'tecnología';
  useCase = 'captacion';
  adjectives = 'técnico, claro y orientado a resultados';
  agentName = 'Asistente de ' + companyName;
  faqs = `1. ¿Ofrecéis demo del producto? → "Sí, podemos agendar una demo personalizada. ¿Cuál es vuestra necesidad principal?"
2. ¿Cuánto tarda la implementación? → "Depende del alcance, pero la mayoría de clientes están operativos en menos de 2 semanas."
3. ¿Tenéis soporte técnico? → "Sí, soporte por email y chat en horario laboral, y urgencias 24/7."
4. ¿Se integra con nuestros sistemas? → "Nos integramos con las principales herramientas del mercado. Cuéntame qué usáis."`;
} else {
  faqs = `1. ¿Cuáles son vuestros horarios? → "Nuestro equipo te confirmará los horarios exactos. ¿Quieres que te llamen?"
2. ¿Dónde estáis ubicados? → "Nuestro equipo te dará la dirección exacta y cómo llegar."
3. ¿Hacéis presupuestos sin compromiso? → "Sí, el primer presupuesto es gratuito y sin compromiso."
4. ¿Cómo puedo contactar con vosotros? → "Te paso con nuestro equipo ahora mismo. ¿Me das tu nombre y teléfono?"`;
}

let useCaseBlock = '';
if (useCase === 'citas') {
  useCaseBlock = `1. Saluda y pregunta para qué servicio quieren cita
2. Recoge nombre, preferencia de día/hora y datos de contacto
3. Confirma la petición y di que el equipo confirmará por WhatsApp o email`;
} else if (useCase === 'captacion') {
  useCaseBlock = `1. Saluda y presenta brevemente ${companyName}
2. Genera interés en el servicio/producto
3. Recoge nombre, teléfono y necesidad concreta
4. Confirma que el equipo se pondrá en contacto en menos de 24h`;
} else {
  useCaseBlock = `1. Saluda en nombre de ${companyName} y pregunta en qué puedes ayudar
2. Identifica la necesidad del cliente
3. Resuelve con la información disponible o recoge datos para que el equipo humano contacte
4. Cierra con siguiente paso claro`;
}

const prompt = `# Personalidad

Eres el asistente de voz de ${companyName}, especializado en ${sector}.
Eres ${adjectives}.
Tu nombre es ${agentName}.
IMPORTANTE: Habla SIEMPRE en español, sin excepción, independientemente del idioma en que te hablen.

# Entorno

Atiendes llamadas de clientes potenciales o actuales interesados en ${sector}.
Las conversaciones son por voz, por lo que tus respuestas deben ser cortas y naturales.

# Goal

${useCaseBlock}

# Tono

Profesional pero cercano. Respuestas de máximo 2-3 frases por turno.
Habla siempre en español neutro. Adapta el registro al sector.
Nunca leas listas en voz alta: integra la información en frases naturales.

# Guardrails

Nunca inventes precios, disponibilidad ni compromisos específicos.
Si no sabes algo, di: "Eso te lo confirma directamente nuestro equipo, ¿te llaman hoy mismo?"
No hagas más de una pregunta por turno.
Si el usuario se pone agresivo o el tema es irrelevante, redirige con calma a la función principal.

# FAQs simuladas para ${sector}

${faqs}`;

const firstMessage = `¡Hola! Soy ${agentName}${agentName.startsWith('Asistente') ? '' : ', el asistente'} de ${companyName}. ¿En qué puedo ayudarte?`;

return {
  json: {
    ...data,
    sector,
    useCase,
    agentName,
    prompt,
    firstMessage,
    agentDisplayName: `${companyName} - Agente Demo`
  }
};

const input = $input.first().json;
const agentId = input.agent_id;
const prevData = $('Generate Prompt').first().json;

return {
  json: {
    agent_id: agentId,
    demo_link: `https://elevenlabs.io/app/talk-to?agent_id=${agentId}`,
    edit_link: `https://elevenlabs.io/app/agents/agents/${agentId}`,
    company_name: prevData.company_name,
    contact_name: prevData.contact_name,
    email: prevData.email,
    phone: prevData.phone,
    website: prevData.website,
    appointments_per_week: prevData.appointments_per_week,
    notes: prevData.notes,
    sector: prevData.sector,
    agentName: prevData.agentName
  }
};
